// Build the n8n API request to fetch the last 24 hours of executions
const now = new Date();
const yesterday = new Date(now - 24 * 60 * 60 * 1000);
const baseUrl = $env.N8N_HOST || 'https://mmurawala.app.n8n.cloud';

return [{
  json: {
    api_url: `${baseUrl}/api/v1/executions`,
    period: {
      start: yesterday.toISOString(),
      end: now.toISOString()
    },
    report_date: now.toISOString().split('T')[0],
    params: {
      limit: 1000,
      startedAfter: yesterday.toISOString(),
      startedBefore: now.toISOString()
    }
  }
}];

const input = $input.first().json;
const now = new Date();
const yesterday = new Date(now - 24 * 60 * 60 * 1000);

// Parse executions from the API response
const executions = input.data || input.results || (Array.isArray(input) ? input : []);

let totalCalls = executions.length;
let successful = 0;
let failed = 0;
let totalDuration = 0;
let durationCount = 0;
const byWorkflow = {};

for (const exec of executions) {
  if (exec.status === 'success') successful++;
  else if (exec.status === 'error') failed++;

  if (exec.stoppedAt && exec.startedAt) {
    totalDuration += new Date(exec.stoppedAt) - new Date(exec.startedAt);
    durationCount++;
  }

  const wfName = exec.workflowName || exec.workflowId || 'unknown';
  if (!byWorkflow[wfName]) {
    byWorkflow[wfName] = { total: 0, success: 0, failed: 0 };
  }
  byWorkflow[wfName].total++;
  if (exec.status === 'success') byWorkflow[wfName].success++;
  if (exec.status === 'error') byWorkflow[wfName].failed++;
}

const avgDuration = durationCount > 0 ? Math.round(totalDuration / durationCount) : 0;
const errorRate = totalCalls > 0 ? ((failed / totalCalls) * 100).toFixed(1) : '0.0';
const uptime = totalCalls > 0 ? (((totalCalls - failed) / totalCalls) * 100).toFixed(1) : '100.0';

// Top workflows by volume
const topWorkflows = Object.entries(byWorkflow)
  .sort((a, b) => b[1].total - a[1].total)
  .slice(0, 5)
  .map(([name, stats]) => ({
    workflow: name,
    calls: stats.total,
    error_rate: stats.total > 0 ? ((stats.failed / stats.total) * 100).toFixed(1) + '%' : '0%'
  }));

// Workflows with high error rates
const problemWorkflows = Object.entries(byWorkflow)
  .filter(([_, stats]) => stats.total >= 3 && (stats.failed / stats.total) > 0.1)
  .map(([name, stats]) => `${name}: ${((stats.failed / stats.total) * 100).toFixed(0)}% error rate (${stats.failed}/${stats.total})`)
;

const recommendations = [];
if (parseFloat(errorRate) > 5) recommendations.push(`Overall error rate is ${errorRate}% — investigate failing workflows`);
if (problemWorkflows.length > 0) recommendations.push(`High error rate workflows: ${problemWorkflows.join(', ')}`);
if (totalCalls === 0) recommendations.push('No executions recorded — verify workflows are active');
if (recommendations.length === 0) recommendations.push('All systems operating normally');

const summary = {
  report_date: now.toISOString().split('T')[0],
  period: { start: yesterday.toISOString(), end: now.toISOString() },
  overview: {
    total_executions: totalCalls,
    successful: successful,
    failed: failed,
    avg_response_time: `${avgDuration}ms`,
    uptime: `${uptime}%`,
    error_rate: `${errorRate}%`
  },
  top_workflows: topWorkflows,
  alerts_triggered: failed,
  recommendations: recommendations
};

return [{ json: summary }];

const summary = $input.first().json;

const topWorkflowsText = summary.top_workflows && summary.top_workflows.length > 0
  ? summary.top_workflows.map(w => `  - *${w.workflow}*: ${w.calls} executions (${w.error_rate} errors)`).join('\n')
  : '  No workflow data available';

const recommendationsText = summary.recommendations
  .map((r, i) => `${i + 1}. ${r}`)
  .join('\n');

const statusIcon = parseFloat(summary.overview.error_rate) > 5 ? ':warning:' : ':white_check_mark:';

const slackPayload = {
  blocks: [
    {
      type: 'header',
      text: { type: 'plain_text', text: `Daily Operations Summary - ${summary.report_date}` }
    },
    { type: 'divider' },
    {
      type: 'section',
      text: { type: 'mrkdwn', text: `${statusIcon} *Overview*` }
    },
    {
      type: 'section',
      fields: [
        { type: 'mrkdwn', text: `*Total Executions:*\n${summary.overview.total_executions}` },
        { type: 'mrkdwn', text: `*Successful:*\n${summary.overview.successful}` },
        { type: 'mrkdwn', text: `*Failed:*\n${summary.overview.failed}` },
        { type: 'mrkdwn', text: `*Avg Duration:*\n${summary.overview.avg_response_time}` },
        { type: 'mrkdwn', text: `*Uptime:*\n${summary.overview.uptime}` },
        { type: 'mrkdwn', text: `*Error Rate:*\n${summary.overview.error_rate}` }
      ]
    },
    { type: 'divider' },
    {
      type: 'section',
      text: { type: 'mrkdwn', text: `*Top Workflows (by volume)*\n${topWorkflowsText}` }
    },
    { type: 'divider' },
    {
      type: 'section',
      text: { type: 'mrkdwn', text: `*Recommendations*\n${recommendationsText}` }
    },
    {
      type: 'context',
      elements: [
        { type: 'mrkdwn', text: `Report period: ${summary.period.start} to ${summary.period.end}` }
      ]
    }
  ]
};

return [{ json: slackPayload }];
